			node.Reply(msg, &maelstrom.BroadcastOK{Message: true})

		case "read":
			json.Unmarshal(msg.Body, &read)
			var messages []int
			for _, v := range values {
				messages = append(messages, v)
			}
			node.Reply(msg, &maelstrom.ReadOK{Messages: messages})

